331	### Task 2.1 ∥ R1: word-at-a-time bit unpack + memset RLE fill
332	
333	- Files: `zig-parquet/src/core/encoding/rle.zig` (`decodeBitPacked`, `decode`)
334	- Depends on: Gate 1
335	- Change 1, `decodeBitPacked`: add a fast loop in front of the existing loop, and run the existing
336	  loop only over the remaining outputs.
337	
338	```zig
339	fn decodeBitPacked(data: []const u8, bit_width: u5, output: []u32) !void {
340	    const mask: u64 = (@as(u64, 1) << bit_width) - 1;
341	    var bit_pos: usize = 0;
342	    var i: usize = 0;
343	
344	    // Fast path: one unaligned 8-byte load per value. A value spans at most
345	    // 7 (bit offset) + 31 (bit_width) = 38 bits, so it always fits in the word.
346	    // Runs only while 8 bytes remain; the checked loop below handles the tail.
347	    if (data.len >= 8) {
348	        const last_word = data.len - 8;
349	        while (i < output.len) : (i += 1) {
350	            const byte_pos = bit_pos >> 3;
351	            if (byte_pos > last_word) break;
352	            const word = std.mem.readInt(u64, data[byte_pos..][0..8], .little);
353	            const shift: u6 = @truncate(bit_pos & 7); // 0..7
354	            output[i] = @truncate((word >> shift) & mask); // masked to <= 31 bits
355	            bit_pos += bit_width;
356	        }
357	    }
358	
359	    for (output[i..]) |*out| {
360	        // ... existing loop body, unchanged (it zero-fills past the end of data) ...
361	    }
362	}
363	```
