1	//! RLE/Bit-Packed Hybrid Encoding
2	//!
3	//! This encoding is used for:
4	//! - Definition levels
5	//! - Repetition levels
6	//! - Dictionary indices
7	//!
8	//! The encoding alternates between:
9	//! - RLE runs: repeated value
10	//! - Bit-packed runs: groups of 8 values packed by bit width
11	//!
12	//! Reference: https://parquet.apache.org/docs/file-format/data-pages/encodings/#rle
13	
14	const std = @import("std");
15	const safe = @import("../safe.zig");
16	
17	/// Decode RLE/bit-packed hybrid encoded data
18	/// Returns a slice of u32 values (caller owns the memory)
19	pub fn decode(allocator: std.mem.Allocator, data: []const u8, bit_width: u5, num_values: usize) ![]u32 {
20	    if (bit_width == 0) {
21	        // All values are 0
22	        const result = try allocator.alloc(u32, num_values);
23	        @memset(result, 0);
24	        return result;
25	    }
26	
27	    var result = try allocator.alloc(u32, num_values);
28	    errdefer allocator.free(result);
29	
30	    var pos: usize = 0;
31	    var out_idx: usize = 0;
32	
33	    while (pos < data.len and out_idx < num_values) {
34	        // Read the indicator (varint)
35	        const indicator = readVarInt(data[pos..]) catch break;
36	        pos += indicator.bytes_read;
37	
38	        if (indicator.value & 1 == 1) {
39	            // Bit-packed run
40	            // indicator >> 1 = number of groups of 8 values
41	            const num_groups = indicator.value >> 1;
42	            const num_packed_values = std.math.mul(usize, num_groups, 8) catch return error.EndOfData;
43	
44	            const values_to_read = @min(num_packed_values, num_values - out_idx);
45	            const out_slice = safe.sliceMutOf(u32, result, out_idx, values_to_read) catch return error.EndOfData;
46	            try decodeBitPacked(safe.slice(data, pos, data.len - pos) catch return error.EndOfData, bit_width, out_slice);
47	            out_idx += values_to_read;
48	
49	            // Advance position by the number of bytes used
50	            const total_bits = std.math.mul(usize, num_packed_values, bit_width) catch return error.EndOfData;
51	            const bytes_used = (total_bits + 7) / 8;
52	            pos += bytes_used;
53	        } else {
54	            // RLE run
55	            // indicator >> 1 = repeat count
56	            const repeat_count = indicator.value >> 1;
57	            const values_to_write = @min(repeat_count, num_values - out_idx);
58	
59	            // Read the value (bit_width bits, rounded up to bytes)
60	            const value_bytes = (bit_width + 7) / 8;
61	            if (pos + value_bytes > data.len) break;
62	
63	            var value: u32 = 0;
64	            for (0..value_bytes) |i| {
65	                value |= @as(u32, data[pos + i]) << (safe.castTo(u5, i * 8) catch unreachable); // value_bytes <= 4, so i * 8 <= 24
66	            }
67	            // Mask to bit_width
68	            const mask = (@as(u32, 1) << bit_width) - 1;
69	            value &= mask;
70	            pos += value_bytes;
71	
72	            // Fill with repeated value
73	            for (0..values_to_write) |_| {
74	                result[out_idx] = value;
75	                out_idx += 1;
76	            }
77	        }
78	    }
79	
80	    // Fill remaining with 0 if we didn't get enough values
81	    while (out_idx < num_values) {
82	        result[out_idx] = 0;
83	        out_idx += 1;
84	    }
85	
86	    return result;
87	}
88	
89	/// Decode definition levels (special case for bool output)
90	/// Use this for flat schemas where max_def_level = 1 (just need defined/not-defined)
91	pub fn decodeDefLevels(allocator: std.mem.Allocator, data: []const u8, bit_width: u5, num_values: usize) ![]bool {
92	    const values = try decode(allocator, data, bit_width, num_values);
93	    defer allocator.free(values);
94	
95	    var result = try allocator.alloc(bool, num_values);
96	    for (0..num_values) |i| {
97	        result[i] = values[i] != 0;
98	    }
99	    return result;
100	}
101	
102	/// Decode definition or repetition levels as raw u32 values
103	/// Use this for nested schemas where max_def_level > 1 and you need actual level values
104	pub fn decodeLevels(allocator: std.mem.Allocator, data: []const u8, bit_width: u5, num_values: usize) ![]u32 {
105	    return decode(allocator, data, bit_width, num_values);
106	}
107	
108	/// Decode pure bit-packed levels (without RLE hybrid wrapper)
109	/// This is used for old Parquet files that use BIT_PACKED encoding for definition/repetition levels
110	/// Unlike RLE hybrid, this format has no length prefix and no indicator bytes - just raw bit-packed values
111	pub fn decodeBitPackedLevels(allocator: std.mem.Allocator, data: []const u8, bit_width: u5, num_values: usize) ![]u32 {
112	    const result = try allocator.alloc(u32, num_values);
113	    errdefer allocator.free(result);
114	    try decodeBitPacked(data, bit_width, result);
115	    return result;
116	}
117	
118	/// Calculate the byte size needed for bit-packed levels
119	pub fn bitPackedSize(num_values: usize, bit_width: u5) usize {
120	    return (num_values * bit_width + 7) / 8;
121	}
122	
123	const VarIntResult = struct {
124	    value: usize,
125	    bytes_read: usize,
126	};
127	
128	fn readVarInt(data: []const u8) !VarIntResult {
129	    var result: usize = 0;
130	    var shift: usize = 0;
131	    var i: usize = 0;
132	
133	    const ShiftType = std.math.Log2Int(usize);
134	
135	    while (i < data.len) {
136	        // Check shift before using it to avoid overflow
137	        if (shift >= @bitSizeOf(usize)) return error.VarIntTooLong;
138	
139	        const b = data[i];
140	        i += 1;
141	        result |= @as(usize, b & 0x7F) << (safe.castTo(ShiftType, shift) catch unreachable); // shift < @bitSizeOf(usize) checked above
142	        if (b & 0x80 == 0) {
143	            return .{ .value = result, .bytes_read = i };
144	        }
145	        shift += 7;
146	    }
147	    return error.EndOfData;
148	}
149	
150	fn decodeBitPacked(data: []const u8, bit_width: u5, output: []u32) !void {
151	    var bit_pos: usize = 0;
152	
153	    for (output) |*out| {
154	        const byte_pos = bit_pos / 8;
155	        const bit_offset: u3 = safe.castTo(u3, bit_pos % 8) catch return error.EndOfData;
156	
157	        if (byte_pos >= data.len) {
158	            out.* = 0;
159	            continue;
160	        }
161	
162	        // Read up to 5 bytes to get 32 bits
163	        var value: u64 = 0;
164	        const bytes_needed = (bit_offset + bit_width + 7) / 8;
165	
166	        for (0..bytes_needed) |i| {
167	            if (byte_pos + i < data.len) {
168	                value |= @as(u64, data[byte_pos + i]) << (safe.castTo(u6, i * 8) catch return error.EndOfData);
169	            }
170	        }
171	
172	        // Shift and mask
173	        value >>= bit_offset;
174	        const mask = (@as(u64, 1) << bit_width) - 1;
175	        out.* = safe.castTo(@TypeOf(out.*), value & mask) catch return error.EndOfData;
176	
177	        bit_pos += bit_width;
178	    }
179	}
180	
181	// Tests
182	test "RLE decode simple run" {
183	    const allocator = std.testing.allocator;
184	
185	    // RLE run: indicator = 6 (3 << 1 | 0), value = 0x05
186	    // This means: repeat value 5 three times
187	    const data = [_]u8{ 0x06, 0x05 };
188	    const result = try decode(allocator, &data, 8, 3);
189	    defer allocator.free(result);
190	
191	    try std.testing.expectEqual(@as(usize, 3), result.len);
192	    try std.testing.expectEqual(@as(u32, 5), result[0]);
193	    try std.testing.expectEqual(@as(u32, 5), result[1]);
194	    try std.testing.expectEqual(@as(u32, 5), result[2]);
195	}
196	
197	test "RLE decode bit-packed run" {
198	    const allocator = std.testing.allocator;
199	
